import { DataTypes } from 'sequelize';
import sequelize from '../../config/sequelize.js';

/**
 * ConversationAssignment Model (Sequelize ORM)
 *
 * Tracks assignment of specific customer conversations to individual agents
 * for workload distribution.
 *
 * @property {number} id - Primary key
 * @property {string} phone_number - Customer phone number (conversation identifier, E.164 format)
 * @property {number} line_id - Foreign key to WhatsAppLine
 * @property {number} assigned_user_id - Foreign key to User (agent assigned, NULL if unassigned)
 * @property {Date} assigned_at - Assignment timestamp
 * @property {number} assigned_by_user_id - Foreign key to User (admin/agent who made assignment)
 * @property {string} campaign_id - Campaign ID from which this conversation originated (NULL for manual assignments)
 */
const ConversationAssignment = sequelize.define('ConversationAssignment', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true,
  },
  phone_number: {
    type: DataTypes.STRING(20),
    allowNull: false,
    validate: {
      notNull: {
        msg: 'Phone number is required',
      },
      notEmpty: {
        msg: 'Phone number cannot be empty',
      },
      is: {
        args: /^\+[1-9]\d{1,14}$/,
        msg: 'Phone number must be in E.164 format (e.g., +1234567890)',
      },
    },
  },
  line_id: {
    type: DataTypes.INTEGER,
    allowNull: false,
    references: {
      model: 'whatsapp_lines',
      key: 'id',
    },
    validate: {
      notNull: {
        msg: 'line_id is required',
      },
    },
  },
  assigned_user_id: {
    type: DataTypes.INTEGER,
    allowNull: true,
    references: {
      model: 'users',
      key: 'id',
    },
    comment: 'Agent assigned to conversation (NULL if unassigned)',
  },
  assigned_at: {
    type: DataTypes.DATE,
    allowNull: true,
    comment: 'Assignment timestamp',
  },
  assigned_by_user_id: {
    type: DataTypes.INTEGER,
    allowNull: true,
    references: {
      model: 'users',
      key: 'id',
    },
    comment: 'Admin/agent who made the assignment',
  },
  campaign_id: {
    type: DataTypes.STRING,
    allowNull: true,
    comment: 'Campaign ID from which this conversation originated (NULL for manual assignments)',
  },
}, {
  tableName: 'conversation_assignments',
  timestamps: false, // This table has custom timestamp fields
  underscored: true,
  indexes: [
    {
      name: 'idx_conversation_unique',
      unique: true,
      fields: ['phone_number', 'line_id', 'assigned_user_id'],
      comment: 'Each user can have their own independent conversation with the same phone number'
    },
    {
      name: 'idx_conversation_assigned_user',
      fields: ['assigned_user_id'],
    },
    {
      name: 'idx_conversation_line',
      fields: ['line_id'],
    },
    {
      name: 'idx_conversation_phone',
      fields: ['phone_number'],
    },
    {
      name: 'idx_conversation_campaign',
      fields: ['campaign_id'],
    },
    {
      name: 'idx_conversation_campaign_phone',
      fields: ['campaign_id', 'phone_number'],
    },
  ],
});

export default ConversationAssignment;

