/**
 * Phone Number Normalization Utilities
 *
 * Handles phone number format variations to ensure consistent lookups
 * across the system (e.g., with/without + prefix)
 */

/**
 * Generate phone number variations for database lookups
 * @param {string} phoneNumber - Phone number in any format
 * @returns {string[]} Array of possible phone number formats
 *
 * @example
 * getPhoneVariations('573174945126')
 * // Returns: ['573174945126', '+573174945126']
 *
 * getPhoneVariations('+573174945126')
 * // Returns: ['+573174945126', '573174945126']
 */
export function getPhoneVariations(phoneNumber) {
  if (!phoneNumber) {
    return [];
  }

  const variations = new Set();
  const cleaned = phoneNumber.trim();

  // Add original number
  variations.add(cleaned);

  // Add with + prefix if it doesn't have it
  if (!cleaned.startsWith('+')) {
    variations.add(`+${cleaned}`);
  }

  // Add without + prefix if it has it
  if (cleaned.startsWith('+')) {
    variations.add(cleaned.slice(1));
  }

  return Array.from(variations);
}

/**
 * Normalize phone number to a canonical format (with + prefix)
 * @param {string} phoneNumber - Phone number in any format
 * @returns {string} Normalized phone number with + prefix
 *
 * @example
 * normalizePhoneNumber('573174945126')  // Returns: '+573174945126'
 * normalizePhoneNumber('+573174945126') // Returns: '+573174945126'
 */
export function normalizePhoneNumber(phoneNumber) {
  if (!phoneNumber) {
    return '';
  }

  const cleaned = phoneNumber.trim();

  // Already has + prefix
  if (cleaned.startsWith('+')) {
    return cleaned;
  }

  // Add + prefix
  return `+${cleaned}`;
}

/**
 * Check if two phone numbers are equivalent (ignoring + prefix)
 * @param {string} phone1 - First phone number
 * @param {string} phone2 - Second phone number
 * @returns {boolean} True if numbers are equivalent
 *
 * @example
 * arePhoneNumbersEqual('573174945126', '+573174945126')  // Returns: true
 * arePhoneNumbersEqual('+573174945126', '+573174945126') // Returns: true
 * arePhoneNumbersEqual('573174945126', '573174945127')   // Returns: false
 */
export function arePhoneNumbersEqual(phone1, phone2) {
  if (!phone1 || !phone2) {
    return false;
  }

  const normalized1 = normalizePhoneNumber(phone1);
  const normalized2 = normalizePhoneNumber(phone2);

  return normalized1 === normalized2;
}

