/**
 * Script: Actualización de campaign_id en ConversationAssignments
 * Propósito: Asociar conversaciones con su campaña más reciente
 * Fecha: 2026-01-05
 *
 * Uso:
 *   node src/scripts/updateCampaignAssignments.js [--dry-run]
 *
 * Opciones:
 *   --dry-run    Muestra qué se actualizaría sin hacer cambios
 */

import sequelize from '../config/sequelize.js';
import ConversationAssignment from '../models/sequelize/ConversationAssignment.js';
import Message from '../models/sequelize/Message.js';
import { QueryTypes } from 'sequelize';

const isDryRun = process.argv.includes('--dry-run');

async function updateCampaignAssignments() {
  console.log('========================================');
  console.log('Actualización de campaign_id en ConversationAssignments');
  console.log(`Modo: ${isDryRun ? 'DRY RUN (solo visualización)' : 'PRODUCCIÓN (actualizará datos)'}`);
  console.log('========================================\n');

  try {
    // PASO 1: Obtener registros a actualizar
    console.log('📊 PASO 1: Analizando datos...\n');

    const recordsToUpdate = await sequelize.query(`
      SELECT
          ca.id AS assignment_id,
          ca.phone_number,
          ca.line_id,
          ca.assigned_user_id,
          ca.campaign_id AS current_campaign_id,
          latest_msg.campaign_id AS new_campaign_id,
          latest_msg.campaign_name,
          latest_msg.created_at AS last_campaign_date,
          ca.assigned_at
      FROM conversation_assignments ca
      LEFT JOIN (
          SELECT
              phone_number,
              line_id,
              campaign_id,
              campaign_name,
              created_at,
              ROW_NUMBER() OVER (
                  PARTITION BY phone_number, line_id
                  ORDER BY created_at DESC
              ) as rn
          FROM messages
          WHERE is_mass_campaign = 1
            AND direction = 'outgoing'
            AND campaign_id IS NOT NULL
      ) latest_msg ON latest_msg.phone_number = ca.phone_number
                   AND latest_msg.line_id = ca.line_id
                   AND latest_msg.rn = 1
      WHERE ca.campaign_id IS NULL
         OR (latest_msg.campaign_id IS NOT NULL
             AND ca.campaign_id != latest_msg.campaign_id)
      ORDER BY ca.phone_number, ca.line_id
    `, { type: QueryTypes.SELECT });

    console.log(`Total de registros a actualizar: ${recordsToUpdate.length}\n`);

    if (recordsToUpdate.length === 0) {
      console.log('✅ No hay registros que actualizar. Todos los campaign_id están correctos.\n');
      return;
    }

    // Estadísticas
    const withoutCampaign = recordsToUpdate.filter(r => !r.current_campaign_id).length;
    const withOutdatedCampaign = recordsToUpdate.filter(r => r.current_campaign_id && r.current_campaign_id !== r.new_campaign_id).length;

    console.log('Desglose:');
    console.log(`  - Sin campaign_id: ${withoutCampaign}`);
    console.log(`  - Con campaign_id desactualizado: ${withOutdatedCampaign}\n`);

    // Mostrar primeros 10 registros como ejemplo
    console.log('📋 Primeros registros a actualizar:\n');
    console.table(recordsToUpdate.slice(0, 10).map(r => ({
      assignment_id: r.assignment_id,
      phone: r.phone_number,
      current_campaign: r.current_campaign_id || '(null)',
      new_campaign: r.new_campaign_id,
      campaign_name: r.campaign_name,
      last_sent: new Date(r.last_campaign_date).toLocaleString('es-ES')
    })));

    if (recordsToUpdate.length > 10) {
      console.log(`\n... y ${recordsToUpdate.length - 10} registros más.\n`);
    }

    // PASO 2: Actualizar (si no es dry-run)
    if (isDryRun) {
      console.log('\n🔍 DRY RUN: No se realizaron cambios.');
      console.log('Para aplicar los cambios, ejecuta sin --dry-run:\n');
      console.log('  node src/scripts/updateCampaignAssignments.js\n');
      return;
    }

    console.log('\n⚙️  PASO 2: Actualizando registros...\n');

    let updatedCount = 0;
    let errorCount = 0;

    for (const record of recordsToUpdate) {
      try {
        await ConversationAssignment.update(
          { campaign_id: record.new_campaign_id },
          {
            where: {
              id: record.assignment_id
            }
          }
        );
        updatedCount++;

        if (updatedCount % 50 === 0) {
          console.log(`  Progreso: ${updatedCount}/${recordsToUpdate.length}`);
        }
      } catch (error) {
        errorCount++;
        console.error(`  ❌ Error actualizando assignment ${record.assignment_id}:`, error.message);
      }
    }

    console.log(`\n✅ Actualización completada:`);
    console.log(`  - Registros actualizados: ${updatedCount}`);
    console.log(`  - Errores: ${errorCount}\n`);

    // PASO 3: Verificación post-actualización
    console.log('🔍 PASO 3: Verificación post-actualización...\n');

    const stats = await sequelize.query(`
      SELECT
          COUNT(*) AS total_asignaciones,
          SUM(CASE WHEN campaign_id IS NOT NULL THEN 1 ELSE 0 END) AS con_campaign_id,
          SUM(CASE WHEN campaign_id IS NULL THEN 1 ELSE 0 END) AS sin_campaign_id
      FROM conversation_assignments
    `, { type: QueryTypes.SELECT });

    console.table(stats);

    console.log('\n✅ Script completado exitosamente.\n');

  } catch (error) {
    console.error('\n❌ Error ejecutando el script:', error);
    throw error;
  } finally {
    await sequelize.close();
  }
}

// Ejecutar script
updateCampaignAssignments()
  .then(() => {
    console.log('🎉 Finalizado.');
    process.exit(0);
  })
  .catch((error) => {
    console.error('💥 Error fatal:', error);
    process.exit(1);
  });

