        console.error(`  ❌ Error actualizando assignment ${record.assignment_id}:`, error.message);
      }
    }

    console.log(`\n✅ Actualización completada:`);
    console.log(`  - Registros actualizados: ${updatedCount}`);
    console.log(`  - Errores: ${errorCount}\n`);

