/**
 * POST /api/v1/conversations/:conversationId/assign
 *
 * Assign a conversation to an agent
 * Phase 9: User Story 7 - Conversation Assignment Management
 *
 * Authentication: Required (JWT)
 * Authorization: Admin or agent with line access
 *
 * Request params:
 * - conversationId: format "phoneNumber:lineId" (e.g., "+1234567890:1")
 *
 * Request body:
 * - assignedUserId: number (agent user ID to assign to)
 *
 * Response: 200 OK with assignment details
 */

import express from 'express';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';
import { authorizeLineAccess } from '../../../middleware/authorizeLineAccess.js';
import ConversationAssignmentService from '../../../services/ConversationAssignmentService.js';
import { configureSocketIO } from '../../../config/socketio.js';

const router = express.Router();

/**
 * Parse conversation ID in format "phoneNumber:lineId"
 * @param {string} conversationId
 * @returns {{phoneNumber: string, lineId: number}}
 */
function parseConversationId(conversationId) {
  const parts = conversationId.split(':');
  if (parts.length !== 2) {
    throw new Error('Invalid conversation ID format. Expected phoneNumber:lineId');
  }

  const phoneNumber = parts[0];
  const lineId = parseInt(parts[1], 10);

  if (isNaN(lineId)) {
    throw new Error('Invalid line ID in conversation ID');
  }

  // Validate E.164 format
  if (!/^\+[1-9]\d{1,14}$/.test(phoneNumber)) {
    throw new Error('Invalid phone number format. Expected E.164 format (e.g., +1234567890)');
  }

  return { phoneNumber, lineId };
}

router.post(
  '/:conversationId/assign',
  authenticateJWT,
  async (req, res, next) => {
    try {
      const { conversationId } = req.params;
      const { assignedUserId } = req.body;
      const assignedByUserId = req.user.id;

      // Validate request body
      if (!assignedUserId) {
        return res.status(400).json({
          success: false,
          error: 'assignedUserId is required',
        });
      }

      if (typeof assignedUserId !== 'number' || assignedUserId <= 0) {
        return res.status(400).json({
          success: false,
          error: 'assignedUserId must be a positive number',
        });
      }

      // Parse conversation ID
      let phoneNumber, lineId;
      try {
        ({ phoneNumber, lineId } = parseConversationId(conversationId));
      } catch (error) {
        return res.status(400).json({
          success: false,
          error: error.message,
        });
      }

      // Check if user has access to this line (admin or agent with line access)
      if (req.user.role !== 'admin') {
        const hasAccess = req.user.assignedLines?.some(line => line.id === lineId);
        if (!hasAccess) {
          return res.status(403).json({
            success: false,
            error: 'You do not have access to this line',
          });
        }
      }

      // Assign conversation
      const result = await ConversationAssignmentService.assignConversation(
        phoneNumber,
        lineId,
        assignedUserId,
        assignedByUserId
      );

      // Emit Socket.io event for real-time updates
      const io = configureSocketIO();
      if (io) {
        // Notify the assigned agent
        io.to(`user:${assignedUserId}`).emit('conversation:assigned', {
          phoneNumber,
          lineId,
          conversationId,
          assignment: result.assignment,
          wasReassigned: result.wasReassigned,
        });

        // Notify admins and agents with line access
        io.to(`line:${lineId}`).emit('conversation:assignment_changed', {
          phoneNumber,
          lineId,
          conversationId,
          assignment: result.assignment,
          action: result.wasReassigned ? 'reassigned' : 'assigned',
        });
      }

      res.status(200).json({
        success: true,
        message: result.wasReassigned
          ? 'Conversation reassigned successfully'
          : 'Conversation assigned successfully',
        data: {
          assignment: result.assignment,
          wasReassigned: result.wasReassigned,
        },
      });
    } catch (error) {
      console.error('Error assigning conversation:', error);

      // Handle specific errors
      if (error.message.includes('not found') ||
          error.message.includes('inactive') ||
          error.message.includes('does not have access')) {
        return res.status(400).json({
          success: false,
          error: error.message,
        });
      }

      res.status(500).json({
        success: false,
        error: 'Failed to assign conversation',
        details: process.env.NODE_ENV === 'development' ? error.message : undefined,
      });
    }
  }
);

export default router;

