    21→class ConversationAssignmentService {
    22→  /**
    23→   * Assign a conversation to an agent
    24→   *
    25→   * @param {string} phoneNumber - Customer phone number (E.164 format)
    26→   * @param {number} lineId - WhatsApp line ID
