import ConversationAssignment from '../models/sequelize/ConversationAssignment.js';
import User from '../models/sequelize/User.js';
import WhatsAppLine from '../models/sequelize/WhatsAppLine.js';
import Lead from '../models/sequelize/Lead.js';
import LineUserAssignment from '../models/sequelize/LineUserAssignment.js';
import Message from '../models/sequelize/Message.js';
import sequelize from '../config/sequelize.js';
import { Op } from 'sequelize';

/**
 * ConversationAssignmentService
 *
 * Manages assignment of conversations to agents for workload distribution.
 *
 * Business Rules:
 * - Only agents with access to the line can be assigned
 * - One assignment per conversation (phone_number + line_id)
 * - Cannot assign to inactive users
 * - Reassignment updates assigned_user_id and assigned_at
 */
class ConversationAssignmentService {
  /**
   * Assign a conversation to an agent
   *
   * @param {string} phoneNumber - Customer phone number (E.164 format)
   * @param {number} lineId - WhatsApp line ID
   * @param {number} assignedUserId - Agent user ID to assign to
   * @param {number} assignedByUserId - Admin/agent performing the assignment
   * @returns {Promise<Object>} Assignment record
   * @throws {Error} If validation fails
   */
  async assignConversation(phoneNumber, lineId, assignedUserId, assignedByUserId) {

    // Validate line exists and is active
    const line = await WhatsAppLine.findByPk(lineId);
    if (!line) {
      throw new Error('WhatsApp line not found');
    }
    if (!line.is_active) {
      throw new Error('Cannot assign conversations to an inactive line');
    }

    // Validate assigned user exists, is active, and is an agent
    const assignedUser = await User.findByPk(assignedUserId, {
      include: ['role']
    });
    if (!assignedUser) {
      throw new Error('Assigned user not found');
    }
    if (!assignedUser.is_active) {
      throw new Error('Cannot assign to an inactive user');
    }
    if (assignedUser.role.role_name !== 'agent') {
      throw new Error('Can only assign conversations to agents');
    }

    // Verify agent has access to this line
    const lineAssignment = await LineUserAssignment.findOne({
      where: {
        user_id: assignedUserId,
        line_id: lineId,
      },
    });
    if (!lineAssignment) {
      throw new Error('Agent does not have access to this line');
    }

    // Validate assigning user exists
    const assigningUser = await User.findByPk(assignedByUserId);
    if (!assigningUser) {
      throw new Error('Assigning user not found');
    }

    // Create or update assignment
    const [assignment, created] = await ConversationAssignment.upsert({
      phone_number: phoneNumber,
      line_id: lineId,
      assigned_user_id: assignedUserId,
      assigned_at: new Date(),
      assigned_by_user_id: assignedByUserId,
    }, {
      returning: true,
    });

    // Fetch complete assignment with relations
    const fullAssignment = await ConversationAssignment.findByPk(assignment.id, {
      include: [
        {
          model: User,
          as: 'assignedUser',
          attributes: ['id', 'name', 'email'],
        },
        {
          model: User,
          as: 'assignedByUser',
          attributes: ['id', 'name', 'email'],
        },
        {
          model: WhatsAppLine,
          as: 'line',
          attributes: ['id', 'company_name', 'phone_number'],
        },
      ],
    });

    return {
      assignment: fullAssignment,
      wasReassigned: !created,
    };
  }

  /**
   * Unassign a conversation from an agent
   *
   * @param {string} phoneNumber - Customer phone number (E.164 format)
   * @param {number} lineId - WhatsApp line ID
   * @returns {Promise<boolean>} True if unassigned, false if no assignment found
   */
  async unassignConversation(phoneNumber, lineId) {
    const assignment = await ConversationAssignment.findOne({
      where: {
        phone_number: phoneNumber,
        line_id: lineId,
      },
    });

    if (!assignment) {
      return false;
    }

    // Update assignment to set assigned_user_id to NULL
    await assignment.update({
      assigned_user_id: null,
      assigned_at: null,
    });

    return true;
  }

  /**
   * Get assignment for a conversation
   *
   * @param {string} phoneNumber - Customer phone number (E.164 format)
   * @param {number} lineId - WhatsApp line ID
   * @returns {Promise<Object|null>} Assignment record or null
   */
  async getAssignment(phoneNumber, lineId) {
    const assignment = await ConversationAssignment.findOne({
      where: {
        phone_number: phoneNumber,
        line_id: lineId,
      },
      include: [
        {
          model: User,
          as: 'assignedUser',
          attributes: ['id', 'name', 'email'],
        },
        {
          model: User,
          as: 'assignedByUser',
          attributes: ['id', 'name', 'email'],
        },
        {
          model: WhatsAppLine,
          as: 'line',
          attributes: ['id', 'company_name', 'phone_number'],
        },
      ],
    });

    return assignment;
  }

  /**
   * Get all conversations assigned to a specific agent
   *
   * @param {number} userId - Agent user ID
   * @param {number} lineId - Optional line ID filter
   * @returns {Promise<Array>} Array of assignments
   */
  async getAssignedConversations(userId, lineId = null) {
    const where = {
      assigned_user_id: userId,
    };

    if (lineId) {
      where.line_id = lineId;
    }

    const assignments = await ConversationAssignment.findAll({
      where,
      include: [
        {
          model: WhatsAppLine,
          as: 'line',
          attributes: ['id', 'company_name', 'phone_number'],
        },
      ],
      order: [['assigned_at', 'DESC']],
    });

    return assignments;
  }

  /**
   * Get unassigned conversations for a line
   *
   * @param {number} lineId - WhatsApp line ID
   * @param {number} limit - Maximum number of results (default: 50)
   * @returns {Promise<Array>} Array of unassigned conversation info
   */
  async getUnassignedConversations(lineId, limit = 50) {
    // This is a complex query that needs to find conversations that either:
    // 1. Have no assignment record
    // 2. Have an assignment with assigned_user_id = NULL

    // First get all phone numbers with messages on this line
    const conversations = await Message.findAll({
      attributes: [
        'phone_number',
        [sequelize.fn('MAX', sequelize.col('created_at')), 'last_message_at'],
        [sequelize.fn('COUNT', sequelize.col('id')), 'message_count'],
      ],
      where: {
        line_id: lineId,
        deleted_at: null,
      },
      group: ['phone_number'],
      order: [[sequelize.literal('last_message_at'), 'DESC']],
      limit,
      raw: true,
    });

    // Get assignments for these conversations
    const phoneNumbers = conversations.map(c => c.phone_number);
    const assignments = await ConversationAssignment.findAll({
      where: {
        phone_number: { [Op.in]: phoneNumbers },
        line_id: lineId,
      },
      raw: true,
    });

    // Filter to only unassigned conversations
    const assignmentMap = new Map(
      assignments.map(a => [a.phone_number, a])
    );

    const unassigned = conversations.filter(conv => {
      const assignment = assignmentMap.get(conv.phone_number);
      return !assignment || assignment.assigned_user_id === null;
    });

    return unassigned;
  }

  /**
   * Reassign all conversations from one agent to another
   *
   * @param {number} fromUserId - Source agent user ID
   * @param {number} toUserId - Target agent user ID
   * @param {number} lineId - Optional line ID filter
   * @param {number} reassignedByUserId - Admin performing reassignment
   * @returns {Promise<number>} Number of conversations reassigned
   */
  async bulkReassign(fromUserId, toUserId, lineId = null, reassignedByUserId) {
    // Validate target user
    const targetUser = await User.findByPk(toUserId, {
      include: ['role']
    });
    if (!targetUser || !targetUser.is_active) {
      throw new Error('Target user not found or inactive');
    }
    if (targetUser.role.role_name !== 'agent') {
      throw new Error('Can only reassign to agents');
    }

    const where = {
      assigned_user_id: fromUserId,
    };

    if (lineId) {
      where.line_id = lineId;

      // Verify target user has access to this line
      const lineAssignment = await LineUserAssignment.findOne({
        where: {
          user_id: toUserId,
          line_id: lineId,
        },
      });
      if (!lineAssignment) {
        throw new Error('Target agent does not have access to this line');
      }
    }

    const [updateCount] = await ConversationAssignment.update({
      assigned_user_id: toUserId,
      assigned_at: new Date(),
      assigned_by_user_id: reassignedByUserId,
    }, {
      where,
    });

    return updateCount;
  }

  /**
   * Get assignment statistics for a line
   *
   * @param {number} lineId - WhatsApp line ID
   * @returns {Promise<Object>} Assignment statistics
   */
  async getAssignmentStats(lineId) {
    const total = await ConversationAssignment.count({
      where: { line_id: lineId },
    });

    const assigned = await ConversationAssignment.count({
      where: {
        line_id: lineId,
        assigned_user_id: { [Op.ne]: null },
      },
    });

    const unassigned = total - assigned;

    // Get per-agent counts
    const agentCounts = await ConversationAssignment.findAll({
      attributes: [
        'assigned_user_id',
        [sequelize.fn('COUNT', sequelize.col('id')), 'count'],
      ],
      where: {
        line_id: lineId,
        assigned_user_id: { [Op.ne]: null },
      },
      include: [
        {
          model: User,
          as: 'assignedUser',
          attributes: ['id', 'name', 'email'],
        },
      ],
      group: ['assigned_user_id'],
      raw: false,
    });

    return {
      total,
      assigned,
      unassigned,
      byAgent: agentCounts.map(item => ({
        userId: item.assigned_user_id,
        userName: item.assignedUser ? item.assignedUser.name : 'Unknown',
        count: parseInt(item.dataValues.count, 10),
      })),
    };
  }
}

export default new ConversationAssignmentService();

