/**
 * Save an outgoing message sent by an agent
 * @param {Object} messageData - Message information
 * @returns {Promise<Object>} Created message
 */
async saveOutgoingMessage(messageData) {
  try {
    // Get or create conversation assignment for manual messages
    // Each user gets their own independent conversation with the same number
    let conversationAssignmentId = null;

    if (messageData.user_id) {
      const [conversationAssignment, created] = await ConversationAssignment.findOrCreate({
        where: {
          phone_number: messageData.phone_number,
          line_id: messageData.line_id,
          assigned_user_id: messageData.user_id,
          campaign_id: messageData.campaign_id,

        },
        defaults: {
          assigned_at: new Date(),
          assigned_by_user_id: messageData.user_id
        }
      });

      // CRITICAL: Update assigned_at every time this user sends a message
      // This ensures replies go to the LAST user who contacted this number
      if (!created) {
        await conversationAssignment.update({
          assigned_at: new Date()
        });
      }

      conversationAssignmentId = conversationAssignment.id;
    }

    const message = await Message.create({
      line_id: messageData.line_id,
      lead_id: messageData.lead_id,
      user_id: messageData.user_id,
      template_id: messageData.template_id || null,
      phone_number: messageData.phone_number,
      message_content: messageData.message_content || '',
      message_type: messageData.message_type || 'text',
      direction: 'outgoing',
      status: messageData.status || 'pending',
      file_url: messageData.file_url || null,
      is_mass_campaign: messageData.is_mass_campaign || false,
      meta_message_id: messageData.meta_message_id || null,
      reply_to_message_id: messageData.reply_to_message_id || null,
      conversation_assignment_id: conversationAssignmentId, // Link to conversation
      interactive_type: messageData.interactive_type || null,
      interactive_data: messageData.interactive_data || null,
    });

    return message.toJSON();
  } catch (error) {
    throw new Error(`Error saving outgoing message: ${error.message}`);
  }
}

/**
 * Update message status (for delivery tracking)
 * @param {string} metaMessageId - Meta's message ID
 * @param {string} status - New status (sent, delivered, read, failed)
 * @returns {Promise<Object|null>} Updated message or null
 */
async updateMessageStatus(metaMessageId, status) {
  try {
    const message = await Message.findOne({
      where: { meta_message_id: metaMessageId },
    });

    if (!message) {
      return null;
    }

    await message.update({ status });
    return message.toJSON();

