/**
 * Message Service
 *
 * Manages WhatsApp message CRUD operations using Sequelize ORM.
 * Handles incoming and outgoing messages with soft deletes (paranoid mode).
 *
 * Phase D: Sequelize implementation
 */

import { Lead, User, WhatsAppLine, ConversationAssignment } from '../models/sequelize/associations.js';
import Message  from '../models/sequelize/Message.js';
import { Op } from 'sequelize';
import sequelize from '../config/sequelize.js';

class MessageService {
  /**
   * Save an incoming message from WhatsApp webhook
   * @param {Object} messageData - Message information
   * @returns {Promise<Object>} Created message
   */
  async saveIncomingMessage(messageData) {
    try {
      // Find the most recent conversation_assignment for this phone_number + line_id
      // This ensures the reply goes to the last user who contacted this number
      const latestAssignment = await ConversationAssignment.findOne({
        where: {
          phone_number: messageData.phone_number,
          line_id: messageData.line_id
        },
        order: [['assigned_at', 'DESC']]
      });

      const message = await Message.create({
        line_id: messageData.line_id,
        lead_id: messageData.lead_id,
        phone_number: messageData.phone_number,
        message_content: messageData.message_content || '',
        message_type: messageData.message_type || 'text',
        direction: 'incoming',
        status: 'received',
        file_url: messageData.file_url || null,
        meta_message_id: messageData.meta_message_id,
        reply_to_message_id: messageData.reply_to_message_id || null,
        campaign_id: messageData.campaign_id || null,
        assigned_user_id: messageData.assigned_user_id || null,
        assigned_user_ids: messageData.assigned_user_ids || null, // Array of assigned agents
        conversation_assignment_id: latestAssignment ? latestAssignment.id : null, // Assign to latest conversation
        interactive_type: messageData.interactive_type || null,
        interactive_data: messageData.interactive_data || null,
      });

      return message.toJSON();
    } catch (error) {
      // Handle duplicate meta_message_id (webhook retries)
      if (error.name === 'SequelizeUniqueConstraintError') {
        const existing = await Message.findOne({
          where: { meta_message_id: messageData.meta_message_id },
        });
        return existing ? existing.toJSON() : null;
      }
      throw new Error(`Error saving incoming message: ${error.message}`);
    }
  }

  /**
   * Save an outgoing message sent by an agent
   * @param {Object} messageData - Message information
   * @returns {Promise<Object>} Created message
   */
  async saveOutgoingMessage(messageData) {
    try {
      // Get or create conversation assignment for manual messages
      // Each user gets their own independent conversation with the same number
      let conversationAssignmentId = null;

      if (messageData.user_id) {
        const [conversationAssignment, created] = await ConversationAssignment.findOrCreate({
          where: {
            phone_number: messageData.phone_number,
            line_id: messageData.line_id,
            assigned_user_id: messageData.user_id,
            campaign_id: messageData.campaign_id,

          },
          defaults: {
            assigned_at: new Date(),
            assigned_by_user_id: messageData.user_id
          }
        });

        // CRITICAL: Update assigned_at every time this user sends a message
        // This ensures replies go to the LAST user who contacted this number
        if (!created) {
          await conversationAssignment.update({
            assigned_at: new Date()
          });
        }

        conversationAssignmentId = conversationAssignment.id;
      }

      const message = await Message.create({
        line_id: messageData.line_id,
        lead_id: messageData.lead_id,
        user_id: messageData.user_id,
        template_id: messageData.template_id || null,
        phone_number: messageData.phone_number,
        message_content: messageData.message_content || '',
        message_type: messageData.message_type || 'text',
        direction: 'outgoing',
        status: messageData.status || 'pending',
        file_url: messageData.file_url || null,
        is_mass_campaign: messageData.is_mass_campaign || false,
        meta_message_id: messageData.meta_message_id || null,
        reply_to_message_id: messageData.reply_to_message_id || null,
        conversation_assignment_id: conversationAssignmentId, // Link to conversation
        interactive_type: messageData.interactive_type || null,
        interactive_data: messageData.interactive_data || null,
      });

      return message.toJSON();
    } catch (error) {
      throw new Error(`Error saving outgoing message: ${error.message}`);
    }
  }

  /**
   * Update message status (for delivery tracking)
   * @param {string} metaMessageId - Meta's message ID
   * @param {string} status - New status (sent, delivered, read, failed)
   * @returns {Promise<Object|null>} Updated message or null
   */
  async updateMessageStatus(metaMessageId, status) {
    try {
      const message = await Message.findOne({
        where: { meta_message_id: metaMessageId },
      });

      if (!message) {
        return null;
      }

      await message.update({ status });
      return message.toJSON();
    } catch (error) {
      throw new Error(`Error updating message status: ${error.message}`);
    }
  }

  /**
   * Get conversation messages (paginated with cursor)
   * @param {Object} options - Query options
   * @param {string} options.phone_number - Customer phone number
   * @param {number} options.line_id - WhatsApp line ID
   * @param {Date} [options.cursor] - Timestamp cursor for pagination
   * @param {number} [options.limit=50] - Messages per page
   * @returns {Promise<Object>} Messages array and pagination info
   */
  async getConversationMessages(options) {
    try {
      const {
        phone_number,
        line_id,
        cursor,
        limit = 50,
        conversation_assignment_id = null,
      } = options;


      const where = {
        phone_number,
        line_id,
      };

      // Filter by conversation_assignment_id if provided (for agents)
      // Admins don't have this filter, so they see all messages for this phone_number + line_id
      if (conversation_assignment_id !== null) {
        where.conversation_assignment_id = conversation_assignment_id;
        console.log('[MessageService] Filtering messages by conversation_assignment_id:', conversation_assignment_id);
      } else {
        console.log('[MessageService] NOT filtering by conversation_assignment_id (admin or legacy)');
      }

      // Cursor-based pagination (load older messages)
      if (cursor) {
        where.created_at = {
          [Op.lt]: cursor,
        };
      }

      const messages = await Message.findAll({
        where,
        include: [
          {
            model: User,
            as: 'sender',
            attributes: ['id', 'name', 'email'],
          },
          {
            model: Lead,
            as: 'lead',
            attributes: ['id', 'name', 'phone_number'],
            required: false
          },
          {
            model: WhatsAppLine,
            as: 'line',
            attributes: ['id', 'company_name', 'phone_number'],
            required: false
          },
        ],
        order: [['created_at', 'DESC']],
        limit: parseInt(limit),
      });

      return {
        messages: messages.map(m => m.toJSON()),
        has_more: messages.length === parseInt(limit),
        oldest_cursor: messages.length > 0 ? messages[messages.length - 1].created_at : null,
      };
    } catch (error) {
      throw new Error(`Error fetching conversation messages: ${error.message}`);
    }
  }

  /**
   * Get message by ID
   * @param {number} messageId - Message ID
   * @returns {Promise<Object|null>} Message object or null
   */
  async getMessageById(messageId) {
    try {
      const message = await Message.findByPk(messageId, {
        include: [
          {
            model: User,
            as: 'sender',
            attributes: ['id', 'name', 'email'],
          },
          {
            model: Lead,
            as: 'lead',
            attributes: ['id', 'name', 'phone_number'],
          },
          {
            model: WhatsAppLine,
            as: 'line',
            attributes: ['id', 'company_name', 'phone_number'],
          },
        ],
      });

      return message ? message.toJSON() : null;
    } catch (error) {
      throw new Error(`Error fetching message: ${error.message}`);
    }
  }

  /**
   * Get recent conversations for a line (grouped by phone_number)
   * @param {number} lineId - WhatsApp line ID
   * @param {number} [limit=50] - Number of conversations
   * @param {number|null} [userId=null] - User ID for filtering agent conversations
   * @param {number} [offset=0] - Pagination offset
   * @param {string|null} [search=null] - Search term for lead name or phone number
   * @param {string|null} [status=null] - Filter by lead status
   * @returns {Promise<Array>} Conversations with last message info
   */
  async getRecentConversations(lineId, limit = 50, userId = null, offset = 0, search = null, status = null) {
    try {
      // If userId is provided, filter conversations by assignment
      // Use conversation_assignments as source of truth for ownership
      const replacements = [];

      let query = '';

      if (userId) {
        // For agents: Support both new (conversation_assignment_id) and legacy (assigned_user_id) systems
        query = `
          SELECT
            m1.phone_number,
            m1.line_id,
            m1.created_at as last_message_at,
            m1.message_content as last_message,
            m1.direction as last_message_direction,
            m1.campaign_id,
            m1.campaign_name,
            COALESCE(ca.assigned_user_id, m1.assigned_user_id) as assigned_user_id,
            m1.assigned_user_ids,
            ca.campaign_id as conversation_campaign_id,
            ca.id as conversation_assignment_id,
            l.id as lead_id,
            l.name as lead_name,
            l.status as lead_status,
            COUNT(CASE WHEN m2.direction = 'incoming' AND m2.status = 'received' THEN 1 END) as unread_count
          FROM messages m1
          LEFT JOIN conversation_assignments ca
            ON m1.conversation_assignment_id = ca.id
          LEFT JOIN leads l
            ON m1.phone_number COLLATE utf8mb4_unicode_ci = l.phone_number COLLATE utf8mb4_unicode_ci
          LEFT JOIN messages m2
            ON (
              (m2.conversation_assignment_id IS NOT NULL AND m2.conversation_assignment_id = m1.conversation_assignment_id)
              OR (m2.conversation_assignment_id IS NULL AND m2.phone_number COLLATE utf8mb4_unicode_ci = m1.phone_number COLLATE utf8mb4_unicode_ci AND m2.line_id = m1.line_id)
            )
            AND m2.deleted_at IS NULL
          WHERE m1.deleted_at IS NULL
            AND ca.id IS NOT NULL
            AND ca.assigned_user_id = ?
        `;
        replacements.push(userId);

        // Add line filter
        if (lineId !== null && lineId !== undefined) {
          query += ` AND m1.line_id = ?`;
          replacements.push(lineId);
        }

        // Get the last message for each conversation_assignment_id
        query += `
          AND m1.id = (
            SELECT MAX(id)
            FROM messages m_sub
            WHERE m_sub.deleted_at IS NULL
              AND m_sub.conversation_assignment_id = m1.conversation_assignment_id
          )
        `;
      } else {
        // For admins: Show ALL conversations supporting both new and legacy systems
        query = `
          SELECT
            m1.phone_number,
            m1.line_id,
            m1.created_at as last_message_at,
            m1.message_content as last_message,
            m1.direction as last_message_direction,
            m1.campaign_id,
            m1.campaign_name,
            COALESCE(ca.assigned_user_id, m1.assigned_user_id) as assigned_user_id,
            m1.assigned_user_ids,
            ca.campaign_id as conversation_campaign_id,
            ca.id as conversation_assignment_id,
            l.id as lead_id,
            l.name as lead_name,
            l.status as lead_status,
            COUNT(CASE WHEN m2.direction = 'incoming' AND m2.status = 'received' THEN 1 END) as unread_count
          FROM messages m1
          LEFT JOIN conversation_assignments ca
            ON m1.conversation_assignment_id = ca.id
          LEFT JOIN leads l
            ON m1.phone_number COLLATE utf8mb4_unicode_ci = l.phone_number COLLATE utf8mb4_unicode_ci
          LEFT JOIN messages m2
            ON (
              (m2.conversation_assignment_id IS NOT NULL AND m2.conversation_assignment_id = m1.conversation_assignment_id)
              OR (m2.conversation_assignment_id IS NULL AND m2.phone_number COLLATE utf8mb4_unicode_ci = m1.phone_number COLLATE utf8mb4_unicode_ci AND m2.line_id = m1.line_id)
            )
            AND m2.deleted_at IS NULL
          WHERE m1.deleted_at IS NULL
        `;

        // Add line filter
        if (lineId !== null && lineId !== undefined) {
          query += ` AND m1.line_id = ?`;
          replacements.push(lineId);
        }

        // Get the last message for each conversation (new system) or per user+phone_number (legacy system)
        query += `
          AND m1.id = (
            SELECT MAX(id)
            FROM messages m_sub
            WHERE m_sub.deleted_at IS NULL
              AND (
                (m_sub.conversation_assignment_id IS NOT NULL AND m_sub.conversation_assignment_id = m1.conversation_assignment_id)
                OR (
                  m_sub.conversation_assignment_id IS NULL
                  AND m_sub.phone_number COLLATE utf8mb4_unicode_ci = m1.phone_number COLLATE utf8mb4_unicode_ci
                  AND m_sub.line_id = m1.line_id
                  AND COALESCE(m_sub.assigned_user_id, 0) = COALESCE(m1.assigned_user_id, 0)
                )
              )
          )
        `;
      }

      // Add search filter (applies to both agents and admins)
      if (search) {
        query += ` AND (
          l.name LIKE ?
          OR m1.phone_number LIKE ?
        )`;
        const searchTerm = `%${search}%`;
        replacements.push(searchTerm, searchTerm);
      }

      // Add status filter (applies to both agents and admins)
      if (status) {
        query += ` AND l.status = ?`;
        replacements.push(status);
      }

      query += `
        GROUP BY m1.phone_number, m1.line_id, m1.created_at, m1.message_content, m1.direction, m1.campaign_id, m1.assigned_user_id, m1.assigned_user_ids, ca.assigned_user_id, ca.campaign_id, ca.id, l.id, l.name, l.status
        ORDER BY m1.created_at DESC
        LIMIT ? OFFSET ?
      `;

      replacements.push(limit);
      replacements.push(offset);

      const conversations = await sequelize.query(query, {
        replacements,
        type: sequelize.QueryTypes.SELECT,
      });

      // Debug: Check for duplicates by conversation_assignment_id
      const assignmentIds = conversations.map(c => c.conversation_assignment_id).filter(id => id !== null);
      const uniqueAssignmentIds = [...new Set(assignmentIds)];
      if (assignmentIds.length !== uniqueAssignmentIds.length) {
        console.warn('[MessageService] WARNING: Duplicate conversation_assignment_ids found!', {
          total: assignmentIds.length,
          unique: uniqueAssignmentIds.length
        });
      } else {
        console.log('[MessageService] All conversations are unique (count:', conversations.length, ')');
      }

      // Parse assigned_user_ids from JSON string to array
      return conversations.map(conv => ({
        ...conv,
        assigned_user_ids: conv.assigned_user_ids ?
          (typeof conv.assigned_user_ids === 'string' ? JSON.parse(conv.assigned_user_ids) : conv.assigned_user_ids)
          : null
      }));
    } catch (error) {
      throw new Error(`Error fetching recent conversations: ${error.message}`);
    }
  }

  /**
   * Soft delete a message
   * @param {number} messageId - Message ID
   * @returns {Promise<boolean>} Success status
   */
  async deleteMessage(messageId) {
    try {
      const message = await Message.findByPk(messageId);

      if (!message) {
        throw new Error('Message not found');
      }

      await message.destroy(); // Soft delete (sets deleted_at)
      return true;
    } catch (error) {
      throw new Error(`Error deleting message: ${error.message}`);
    }
  }

  /**
   * Get message statistics for a line
   * @param {number} lineId - WhatsApp line ID
   * @param {Date} [startDate] - Start date for stats
   * @param {Date} [endDate] - End date for stats
   * @returns {Promise<Object>} Message statistics
   */
  async getMessageStats(lineId, startDate, endDate) {
    try {
      const where = {
        line_id: lineId,
      };

      if (startDate && endDate) {
        where.created_at = {
          [Op.between]: [startDate, endDate],
        };
      }

      const stats = await Message.findAll({
        where,
        attributes: [
          'direction',
          'status',
          [sequelize.fn('COUNT', sequelize.col('id')), 'count'],
        ],
        group: ['direction', 'status'],
      });

      const result = {
        incoming: 0,
        outgoing: 0,
        sent: 0,
        delivered: 0,
        read: 0,
        failed: 0,
      };

      stats.forEach(stat => {
        const direction = stat.direction;
        const status = stat.status;
        const count = parseInt(stat.get('count'));

        result[direction] += count;
        result[status] += count;
      });

      return result;
    } catch (error) {
      throw new Error(`Error fetching message stats: ${error.message}`);
    }
  }

  /**
   * Mark conversation messages as read
   * @param {string} phoneNumber - Customer phone number
   * @param {number} lineId - WhatsApp line ID
   * @returns {Promise<number>} Number of messages updated
   */
  async markConversationAsRead(phoneNumber, lineId) {
    try {
      const [affectedCount] = await Message.update(
        { status: 'read' },
        {
          where: {
            phone_number: phoneNumber,
            line_id: lineId,
            direction: 'incoming',
            status: 'received',
          },
        }
      );

      return affectedCount;
    } catch (error) {
      throw new Error(`Error marking conversation as read: ${error.message}`);
    }
  }
}

export default new MessageService();

/**
 * Script: Actualización de campaign_id en MENSAJES DE RESPUESTA
 * Propósito: Asociar respuestas de clientes con la campaña que les enviamos
 * Fecha: 2026-01-05
 *
 * Uso:
 *   node src/scripts/updateResponseMessagesCampaign.js [--dry-run]
 *
 * Opciones:
 *   --dry-run    Muestra qué se actualizaría sin hacer cambios
 */

import sequelize from '../config/sequelize.js';
import Message from '../models/sequelize/Message.js';
import { QueryTypes } from 'sequelize';

const isDryRun = process.argv.includes('--dry-run');

async function updateResponseMessages() {
  console.log('========================================');
  console.log('Actualización de campaign_id en MENSAJES DE RESPUESTA');
  console.log(`Modo: ${isDryRun ? 'DRY RUN (solo visualización)' : 'PRODUCCIÓN (actualizará datos)'}`);
  console.log('========================================\n');

  try {
    // PASO 0: Estadísticas generales
    console.log('📊 PASO 0: Estadísticas de mensajes entrantes...\n');

    const generalStats = await sequelize.query(`
      SELECT
          COUNT(*) AS total_incoming,
          SUM(CASE WHEN campaign_id IS NOT NULL THEN 1 ELSE 0 END) AS with_campaign,
          SUM(CASE WHEN campaign_id IS NULL THEN 1 ELSE 0 END) AS without_campaign
      FROM messages
      WHERE direction = 'incoming'
        AND deleted_at IS NULL
    `, { type: QueryTypes.SELECT });

    console.log('Estado actual de mensajes INCOMING:');
    console.table(generalStats);

    // PASO 1: Identificar mensajes a actualizar
    console.log('\n📊 PASO 1: Identificando respuestas sin campaign_id...\n');

    const messagesToUpdate = await sequelize.query(`
      SELECT
          incoming.id AS message_id,
          incoming.phone_number,
          incoming.line_id,
          incoming.created_at AS response_date,
          incoming.campaign_id AS current_campaign_id,
          latest_campaign.campaign_id AS new_campaign_id,
          latest_campaign.campaign_name,
          latest_campaign.assigned_user_id,
          latest_campaign.assigned_user_ids,
          latest_campaign.sent_at AS campaign_sent_date,
          TIMESTAMPDIFF(MINUTE, latest_campaign.sent_at, incoming.created_at) AS minutes_after
      FROM messages incoming
      INNER JOIN (
          SELECT
              m.phone_number,
              m.line_id,
              m.campaign_id,
              m.campaign_name,
              m.assigned_user_id,
              m.assigned_user_ids,
              m.created_at AS sent_at,
              ROW_NUMBER() OVER (
                  PARTITION BY m.phone_number, m.line_id
                  ORDER BY m.created_at DESC
              ) AS rn
          FROM messages m
          WHERE m.is_mass_campaign = 1
            AND m.direction = 'outgoing'
            AND m.campaign_id IS NOT NULL
            AND m.deleted_at IS NULL
      ) latest_campaign
          ON latest_campaign.phone_number = incoming.phone_number
          AND latest_campaign.line_id = incoming.line_id
          AND latest_campaign.rn = 1
          AND latest_campaign.sent_at < incoming.created_at
      WHERE incoming.direction = 'incoming'
        AND incoming.campaign_id IS NULL
        AND incoming.deleted_at IS NULL
      ORDER BY incoming.created_at DESC
    `, { type: QueryTypes.SELECT });

    console.log(`Total de respuestas a actualizar: ${messagesToUpdate.length}\n`);

    if (messagesToUpdate.length === 0) {
      console.log('✅ No hay mensajes de respuesta que actualizar. Todos tienen campaign_id correcto.\n');
      return;
    }

    // Estadísticas de respuestas por campaña
    const campaignBreakdown = messagesToUpdate.reduce((acc, msg) => {
      const key = msg.new_campaign_id;
      if (!acc[key]) {
        acc[key] = { campaign_id: key, campaign_name: msg.campaign_name, count: 0 };
      }
      acc[key].count++;
      return acc;
    }, {});

    console.log('Respuestas por campaña:');
    console.table(Object.values(campaignBreakdown));

    // Mostrar primeros 10 mensajes como ejemplo
    console.log('\n📋 Primeros mensajes a actualizar:\n');
    console.table(messagesToUpdate.slice(0, 10).map(m => ({
      message_id: m.message_id,
      phone: m.phone_number,
      current_campaign: m.current_campaign_id || '(null)',
      new_campaign: m.new_campaign_id,
      campaign_name: m.campaign_name,
      response_date: new Date(m.response_date).toLocaleString('es-ES'),
      minutes_after: m.minutes_after
    })));

    if (messagesToUpdate.length > 10) {
      console.log(`\n... y ${messagesToUpdate.length - 10} mensajes más.\n`);
    }

    // PASO 2: Actualizar (si no es dry-run)
    if (isDryRun) {
      console.log('\n🔍 DRY RUN: No se realizaron cambios.');
      console.log('Para aplicar los cambios, ejecuta sin --dry-run:\n');
      console.log('  node src/scripts/updateResponseMessagesCampaign.js\n');
      return;
    }

    console.log('\n⚙️  PASO 2: Actualizando mensajes...\n');

    let updatedCount = 0;
    let errorCount = 0;

    // Actualizar en lotes para mejor rendimiento
    const BATCH_SIZE = 100;
    for (let i = 0; i < messagesToUpdate.length; i += BATCH_SIZE) {
      const batch = messagesToUpdate.slice(i, i + BATCH_SIZE);

      try {
        await sequelize.transaction(async (t) => {
          for (const msg of batch) {
            await Message.update(
              {
                campaign_id: msg.new_campaign_id,
                campaign_name: msg.campaign_name,
                // Solo actualizar assigned_user_ids si están vacíos
                assigned_user_id: msg.assigned_user_id || undefined,
                assigned_user_ids: msg.assigned_user_ids || undefined
              },
              {
                where: { id: msg.message_id },
                transaction: t
              }
            );
            updatedCount++;
          }
        });

        console.log(`  Progreso: ${updatedCount}/${messagesToUpdate.length}`);
      } catch (error) {
        errorCount += batch.length;
        console.error(`  ❌ Error actualizando lote en índice ${i}:`, error.message);
      }
    }

    console.log(`\n✅ Actualización completada:`);
    console.log(`  - Mensajes actualizados: ${updatedCount}`);
    console.log(`  - Errores: ${errorCount}\n`);

    // PASO 3: Verificación post-actualización
    console.log('🔍 PASO 3: Verificación post-actualización...\n');

    const finalStats = await sequelize.query(`
      SELECT
          COUNT(*) AS total_incoming,
          SUM(CASE WHEN campaign_id IS NOT NULL THEN 1 ELSE 0 END) AS with_campaign,
          SUM(CASE WHEN campaign_id IS NULL THEN 1 ELSE 0 END) AS without_campaign,
          ROUND(SUM(CASE WHEN campaign_id IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS porcentaje_con_campaign
      FROM messages
      WHERE direction = 'incoming'
        AND deleted_at IS NULL
    `, { type: QueryTypes.SELECT });

    console.log('Estado final:');
    console.table(finalStats);

    // Verificar respuestas por campaña
    const responsesPerCampaign = await sequelize.query(`
      SELECT
          campaign_id,
          campaign_name,
          COUNT(*) AS total_respuestas,
          COUNT(DISTINCT phone_number) AS clientes_unicos
      FROM messages
      WHERE direction = 'incoming'
        AND campaign_id IS NOT NULL
        AND deleted_at IS NULL
      GROUP BY campaign_id, campaign_name
      ORDER BY total_respuestas DESC
      LIMIT 10
    `, { type: QueryTypes.SELECT });

    console.log('\nTop 10 campañas con más respuestas:');
    console.table(responsesPerCampaign);

    console.log('\n✅ Script completado exitosamente.\n');

  } catch (error) {
    console.error('\n❌ Error ejecutando el script:', error);
    throw error;
  } finally {
    await sequelize.close();
  }
}

// Ejecutar script
updateResponseMessages()
  .then(() => {
    console.log('🎉 Finalizado.');
    process.exit(0);
  })
  .catch((error) => {
    console.error('💥 Error fatal:', error);
    process.exit(1);
  });

